// Goldleaf v2.0.7: lighter sync and a focused hallmark charge calculator.
const v2OriginalEnsure=window.ensureExtendedData;
window.ensureExtendedData=function(){
  v2OriginalEnsure();
  db.rates=Object.assign({gold24:0,gold22:0,gold18:0,gold14:0,karatMode:'automatic',silver:0,oldSilver:0,updatedAt:''},db.rates||{});
  if(!Array.isArray(db.rateHistory))db.rateHistory=[];
};
ensureExtendedData();

function v2RateForPurity(purity,rates=db.rates){
  const k=Number(purity)||0,mode=rates.karatMode||'automatic';
  if(k===24)return n(rates.gold24);
  if(k===22)return mode==='manual'&&n(rates.gold22)>0?n(rates.gold22):n(rates.gold24)*22/24;
  if(k===18)return mode==='manual'&&n(rates.gold18)>0?n(rates.gold18):n(rates.gold24)*18/24;
  if(k===14)return mode==='manual'&&n(rates.gold14)>0?n(rates.gold14):n(rates.gold24)*14/24;
  return n(rates.gold24)*k/24;
}
window.setKaratRateMode=function(mode){
  const form=document.getElementById('rateBookForm');if(!form)return;
  mode=mode==='manual'?'manual':'automatic';
  form.elements.karatMode.value=mode;
  form.querySelectorAll('[data-karat-mode]').forEach(button=>button.classList.toggle('active',button.dataset.karatMode===mode));
  form.querySelectorAll('[data-karat-rate]').forEach(input=>input.readOnly=mode==='automatic');
  updateRatePreview(form);
};
window.rateBookView=function(){
  ensureExtendedData();const r=db.rates,mode=r.karatMode||'automatic';
  const fmtRate=value=>rateMoney(value||0);
  const rows=db.rateHistory.slice(0,12).map(item=>{const v=item.rates||{};return [esc(item.date+' '+item.time+' IST'),esc(item.slot||''),esc(v.karatMode==='manual'?'Manual':'Automatic'),fmtRate(v.gold24),fmtRate(v.gold22||n(v.gold24)*22/24),fmtRate(v.gold18||n(v.gold24)*18/24),fmtRate(v.gold14||n(v.gold24)*14/24),fmtRate(v.silver),fmtRate(v.oldSilver)]});
  const karatField=(karat,value)=>'<div class="field"><label>Gold · '+karat+'K · ₹/g</label><input data-karat-rate="'+karat+'" name="gold'+karat+'" type="number" min=".01" step=".01" value="'+(n(value)||'')+'" '+(mode==='automatic'?'readonly':'')+' oninput="updateRatePreview(this.form)" required></div>';
  return header('Set the 24K base and choose automatic or manual prices for 22K, 18K and 14K.')
   +'<section class="panel"><h2>Today’s rates</h2><form id="rateBookForm" onsubmit="saveRateBook(event)"><div class="grid">'
   +rateMoneyInput('Gold · 24K base · ₹/g *','gold24',r.gold24,'oninput="updateRatePreview(this.form)" required')
   +'<div class="field wide"><label>22K / 18K / 14K rate entry</label><input type="hidden" name="karatMode" value="'+mode+'"><div class="rate-mode-switch"><button type="button" data-karat-mode="automatic" class="'+(mode==='automatic'?'active':'')+'" onclick="setKaratRateMode(\'automatic\')">Automatic</button><button type="button" data-karat-mode="manual" class="'+(mode==='manual'?'active':'')+'" onclick="setKaratRateMode(\'manual\')">Enter manually</button></div><span class="muted">Automatic rates use the 24K base. Manual rates use the values you enter below.</span></div>'
   +karatField(22,n(r.gold22)||n(r.gold24)*22/24)+karatField(18,n(r.gold18)||n(r.gold24)*18/24)+karatField(14,n(r.gold14)||n(r.gold24)*14/24)
   +rateMoneyInput('Silver · ₹/g *','silver',r.silver,'required')+rateMoneyInput('Old silver · ₹/g *','oldSilver',r.oldSilver,'required')
   +'</div><p class="muted">Last saved: '+(r.updatedAt?new Date(r.updatedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST':'No rates saved yet.')+'</p><div class="right"><button class="primary">Save today’s rates</button></div></form></section>'
   +'<section class="panel"><h2>Rate update history</h2>'+(rows.length?table(['Date and time','Update','Mode','24K gold','22K gold','18K gold','14K gold','Silver','Old silver'],rows):'<div class="empty">Rate changes will appear here after the first save.</div>')+'</section>';
};
window.updateRatePreview=function(form){
  if(!form)return;const mode=form.elements.karatMode?.value||'automatic',base=n(form.elements.gold24?.value);
  form.querySelectorAll('[data-karat-rate]').forEach(input=>{input.readOnly=mode==='automatic';if(mode==='automatic')input.value=(base*Number(input.dataset.karatRate)/24).toFixed(2)});
};
window.saveRateValues=function(form,slot){
  const f=new FormData(form),mode=f.get('karatMode')==='manual'?'manual':'automatic',gold24=n(f.get('gold24'));
  const rates={gold24,gold22:mode==='manual'?n(f.get('gold22')):gold24*22/24,gold18:mode==='manual'?n(f.get('gold18')):gold24*18/24,gold14:mode==='manual'?n(f.get('gold14')):gold24*14/24,karatMode:mode,silver:n(f.get('silver')),oldSilver:n(f.get('oldSilver')),oldGold:n(db.rates.oldGold),updatedAt:new Date().toISOString()};
  if(gold24<=0||rates.silver<=0||rates.oldSilver<=0||(mode==='manual'&&[rates.gold22,rates.gold18,rates.gold14].some(value=>value<=0))){say('Enter a valid 24K, silver, old silver and manual karat rate.');return false}
  const now=new Date(),when=istDateTime(now);db.rates=rates;db.rateHistory.unshift({id:crypto.randomUUID(),date:when.date,time:when.time,slot:slot||'Manual',rates:Object.assign({},rates)});db.rateHistory=db.rateHistory.slice(0,100);save();return true;
};
window.saveRateBook=function(event){event.preventDefault();if(!saveRateValues(event.target,'Manual'))return;render();say('Rates saved.')};
window.updateHistoryView=function(){return header('A separate record of website updates and features.')+'<section class="panel"><h2>Current version</h2><p><b>Goldleaf v2.0.7</b> · 6 Nov 2026</p><p class="hint">Review the changes included in each website update here.</p></section><section class="panel"><h2>Update history</h2><article class="release-note"><h3>v2.0.7 · 6 Nov 2026 · Current</h3><ul><li>Prevented overlapping cloud checks and reduced background checks while keeping saves immediate.</li><li>Kept active entries open during remote updates and made hallmark charge typing update only its total.</li></ul></article><article class="release-note"><h3>v2.0.6 · 6 Nov 2026</h3><ul><li>Removed Customer switching and Customer sections from Party Ledger.</li><li>Kept Party Ledger and Party pages in Wholesale; all Customer pages stay in Retail.</li></ul></article><article class="release-note"><h3>v2.0.5 · 6 Nov 2026</h3><ul><li>Added optional HUID and Non-HUID hallmark charges to Wholesale Party Sales, calculated as pieces × charge per piece.</li><li>Added separate gold-gram and hallmark-rupee balances to Party Ledger and its PDF, with cash allocation and high-contrast balance cards.</li><li>Kept Party pages in Wholesale and Customer pages in Retail.</li></ul></article><article class="release-note"><h3>v2.0.4 · 6 Nov 2026</h3><ul><li>Made phone and laptop sync automatic on sign-in, saves and background refresh.</li><li>Removed the manual sync button from Settings.</li></ul></article><article class="release-note"><h3>v2.0.3 · 6 Nov 2026</h3><ul><li>Made both devices merge their local and cloud records during sign-in, saves and refresh.</li><li>Removed replace actions to protect records on both devices.</li></ul></article><article class="release-note"><h3>v2.0.2 · 6 Nov 2026</h3><ul><li>Prevented empty email/password submissions from reaching cloud sign-up as anonymous login attempts.</li><li>Added clearer first-account, verification and sign-in error instructions.</li></ul></article><article class="release-note"><h3>v2.0.1 · 6 Nov 2026</h3><ul><li>Added phone-to-cloud and cloud-to-laptop replacement steps with confirmation.</li><li>Made saves merge with the latest cloud ledger safely and refreshed open devices every 5 seconds.</li></ul></article><article class="release-note"><h3>v2.0.0 · 6 Nov 2026</h3><ul><li>Added automatic or manual 22K, 18K and 14K prices; removed the Old Gold rate field from Rate Book.</li><li>Updated Retail bills to use the Rate Book without showing a 24K rate box, and added Cash, Cheque and GPay collection details.</li><li>Expanded Customer and Party ledgers with purchase, payment, old gold, grams, pending balance and running balance reports, plus PDF/print and share actions.</li><li>Added same-account sync guidance, first-sign-in merging, manual sync and background refresh while the app is open.</li></ul></article><article class="release-note"><h3>v1.9.0 · 5 Nov 2026</h3><ul><li>Added a separate collected amount that reduces Retail customer balance and appears as a bill collection in the customer ledger and summary.</li><li>Improved Balance Due contrast and added Classic and Modern print templates for customer bills.</li></ul></article><article class="release-note"><h3>v1.8.0 · 5 Nov 2026</h3><ul><li>Fixed Retail Customer Sales Entry to keep bill details and balance visible without page scrolling.</li><li>Old Gold Exchange opens only from its button, and customer sales history opens separately.</li></ul></article><article class="release-note"><h3>v1.7.0 · 5 Nov 2026</h3><ul><li>Made Retail customer sales a single continuous view with account details, jewellery, calculations, discount and balance together.</li><li>Moved Old Gold Exchange into an optional panel and restored the simpler Wholesale party sale form.</li></ul></article><article class="release-note"><h3>v1.6.0 · 5 Nov 2026</h3><ul><li>Added separate Retail and Wholesale workspaces with matching navigation, accounts, sales, payments, ledgers and summaries.</li></ul></article><article class="release-note"><h3>v1.5.0 · 5 Nov 2026</h3><ul><li>Added one-screen customer and party bills with discounts, final balances and itemized old gold exchange.</li></ul></article><article class="release-note"><h3>v1.4.0 · 5 Nov 2026</h3><ul><li>Combined Party and Customer summary and ledger pages with separate Party and Customer tabs.</li></ul></article><article class="release-note"><h3>v1.3.0 · 5 Nov 2026</h3><ul><li>Combined Party Register and Customer Register on one Register page with Party and Customer tabs.</li></ul></article><article class="release-note"><h3>v1.2.0 · 5 Nov 2026</h3><ul><li>Added customer sale calculations, Rate Book, rate reminders, and website update history.</li></ul></article><article class="release-note"><h3>v1.1.0 · 5 Nov 2026</h3><ul><li>Added customer registration, separate rupee ledger and summary, themes and home-screen install support.</li></ul></article></section>'};

const v2PreviousSalesView=window.salesView;
function v2Historical24Rate(sale,purity){return n(sale?.ratePerGram)>0?n(sale.ratePerGram)*24/(Number(purity)||24):n(sale?.rate24)||v2RateForPurity(purity)*24/(Number(purity)||24)}
function v2HallmarkAmount(sale){return Math.round((n(sale?.hallmarkChargeAmount)||n(sale?.pieces)*n(sale?.hallmarkChargePerPiece))*100)/100}
function v2PartySaleView(){
  const x=db.sales.find(item=>item.id===edit&&ownerType(item)==='party'),when=x?.when||new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),city=accountCity(x?.partyId,'party');
  const products=db.products.map(item=>'<option '+(item===x?.product?'selected':'')+'>'+esc(item)+'</option>').join(''),purities=db.purities.map(item=>'<option value="'+item+'" '+(Number(item)===Number(x?.purity||22)?'selected':'')+'>'+item+'K</option>').join('');
  const hallmarkTotal=v2HallmarkAmount(x),rate=n(x?.hallmarkChargePerPiece),type=x?.hallmarkType||'';
  const form=db.parties.length?'<form id="customerSaleForm" class="v2-party-sale-form" onsubmit="saveSale(event)"><input name="id" type="hidden" value="'+(x?.id||'')+'"><input name="accountType" type="hidden" value="party"><div class="grid">'
    +'<div class="field"><label>Party *</label>'+accountSelect('party',x?.partyId||'')+'</div><div class="field"><label>Place · automatic</label><input name="place" value="'+esc(city||'')+'" readonly></div>'
    +'<div class="field"><label>Date and time</label><input name="when" type="datetime-local" required value="'+when+'"></div><div class="field"><label>Product *</label><select name="product" required>'+products+'</select></div>'
    +'<div class="field"><label>Weight · g *</label><input name="weight" type="number" min=".001" step=".001" required value="'+(x?.weight||'')+'" oninput="calcSale(this.form)"></div><div class="field"><label>Pieces *</label><input name="pieces" type="number" min="1" step="1" required value="'+(x?.pieces||1)+'" oninput="calcSale(this.form)"></div>'
    +'<div class="field"><label>Purity *</label><select name="purity" required onchange="calcSale(this.form)">'+purities+'</select></div><div class="field"><label>Wastage · %</label><input name="wastage" type="number" min="0" step=".01" value="'+(x?.wastage||0)+'" oninput="calcSale(this.form)"></div>'
    +'<div class="field"><label>Hallmark type</label><select name="hallmarkType" onchange="calcHallmarkCharge(this.form)"><option value="" '+(!type?'selected':'')+'>No hallmark</option><option value="HUID" '+(type==='HUID'?'selected':'')+'>HUID</option><option value="Non-HUID" '+(type==='Non-HUID'?'selected':'')+'>Non-HUID</option></select></div><div class="field"><label>Hallmark charge per piece · ₹</label><input name="hallmarkChargePerPiece" type="number" min="0" step=".01" value="'+rate+'" oninput="calcHallmarkCharge(this.form)"></div>'
    +'<div class="field v2-hallmark-total"><label>Total hallmark charge</label><b id="partyHallmarkTotal">'+v2Money(hallmarkTotal)+'</b><small>Pieces × charge per piece</small></div><div class="field"><label>Product photo</label><input name="photo" type="file" accept="image/*"></div>'
    +'<div class="field v2-party-gold-total"><label>Payable pure gold</label><b id="partyGrossSale">'+fmt(x?accountSaleValue(x):0)+' g</b></div></div><div class="right">'+(x?'<button type="button" onclick="edit=null;render()">Cancel</button>':'')+'<button class="primary">'+(x?'Save changes':'Save sale')+'</button></div></form>':'<div class="empty">Register a party before recording a sale.</div>';
  const rows=db.sales.filter(item=>ownerType(item)==='party').sort((a,b)=>b.when.localeCompare(a.when)).map(item=>[item.when.replace('T',' '),esc(accountName(item.partyId,'party')),esc(item.product),fmt(item.weight)+' g',item.pieces||1,item.purity+'K',n(item.wastage)+'%',item.hallmarkType||'—',v2Money(v2HallmarkAmount(item)),fmt(accountSaleValue(item))+' g','<button onclick="edit=\''+item.id+'\';render()">Edit</button>']);
  return header('Wholesale party sales with separate gold and per-piece hallmark charges.')+'<section class="panel"><h2>'+(x?'Edit party sale':'Party sales entry')+'</h2>'+form+'</section><section class="panel"><h2>Party sales history</h2>'+(rows.length?table(['Date','Party','Product','Weight','Pieces','Purity','Wastage','Hallmark','Hallmark ₹','Payable g',''],rows):'<div class="empty">No party sales recorded yet.</div>')+'</section>';
}
window.refreshSalePrice=function(form){
  if(!form||form.elements.accountType.value!=='customer')return;
  const purity=n(form.elements.purity.value),perGram=v2RateForPurity(purity),base=purity>0?perGram*24/purity:0;
  form.elements.rate24.value=base.toFixed(4);if(form.elements.ratePerGram)form.elements.ratePerGram.value=perGram.toFixed(4);
  const label=form.querySelector('#salePurityRateLabel');if(label)label.textContent=perGram>0?rateMoney(perGram)+' / g · '+purity+'K from Rate Book':'Set rates in Rate Book';
  calcSale(form);
};
window.calcHallmarkCharge=function(form){if(!form)return;const total=Math.round(n(form.elements.pieces?.value)*n(form.elements.hallmarkChargePerPiece?.value)*100)/100,node=form.querySelector('#partyHallmarkTotal');if(node)node.textContent=v2Money(total)};
window.calcSale=function(form){
  if(!form)return;const customer=form.elements.accountType.value==='customer',rows=customer?exchangeRows(form):[],exchangeAmount=rows.reduce((a,x)=>a+x.amount,0),exchangePure=rows.reduce((a,x)=>a+x.pureGrams,0),discount=customer?n(form.elements.discount?.value):n(form.elements.partyDiscountGrams?.value);
  const totalLabel=form.querySelector('#exchangeAmountTotal');if(totalLabel)totalLabel.textContent=rateMoney(exchangeAmount);
  const pureLabel=form.querySelector('#exchangePureTotal');if(pureLabel)pureLabel.textContent=fmt(exchangePure)+' g';
  if(customer){
    const totals=customerSaleTotals({weight:form.elements.weight.value,purity:form.elements.purity.value,rate24:form.elements.rate24.value,wastage:form.elements.wastage.value,pieces:form.elements.pieces.value,makingPerPiece:form.elements.makingPerPiece.value,discount});
    const net=totals.final-exchangeAmount,collected=n(form.elements.collectedAmount?.value),due=net-collected,set=(id,value)=>{const node=form.querySelector('#'+id);if(node)node.textContent=value};
    set('saleGoldAmount',rateMoney(totals.goldAmount));set('saleWastageAmount',rateMoney(totals.wastageAmount));set('saleMakingAmount',rateMoney(totals.makingTotal));set('saleSubtotal',rateMoney(totals.subtotal));set('saleAfterDiscount',rateMoney(totals.final));set('saleExchangeAmount',rateMoney(exchangeAmount));set('saleCollectedAmount',rateMoney(collected));set('saleBalanceAmount',rateMoney(Math.abs(due)));set('saleBalanceLabel',due<0?'Customer credit':due===0?'Balance settled':'Balance due');
    if(form.elements.amount)form.elements.amount.value=net.toFixed(2);
    const purityLabel=form.querySelector('#salePurityRateLabel');if(purityLabel)purityLabel.textContent=rateMoney(totals.purityRate)+' / g · '+form.elements.purity.value+'K from Rate Book';
  }else{
    const gross=n(form.elements.weight.value)*n(form.elements.purity.value)/24*(1+n(form.elements.wastage.value)/100),net=gross-discount-exchangePure,hallmark=Math.round(n(form.elements.pieces?.value)*n(form.elements.hallmarkChargePerPiece?.value)*100)/100,set=(id,value)=>{const node=form.querySelector('#'+id);if(node)node.textContent=value};
    set('partyGrossSale',fmt(gross)+' g');set('partyDiscountTotal',fmt(discount)+' g');set('partyExchangePure',fmt(exchangePure)+' g');set('partyNetLabel',net<0?'Gold balance in party favour':'Balance to collect');set('partyNetTotal',fmt(Math.abs(net))+' g');set('partyHallmarkTotal',v2Money(hallmark));
  }
};
